import * as THREE from 'three/webgpu';
import { uv, vec2, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const pos = (config && config.scenePosition) || { x: 3.2, y: -0.3, z: 0 };
  const rot = (config && config.sceneRotation) || { x: 0, y: 0, z: 0 };
  const scl = (config && config.sceneScale) || { x: 1, y: 1, z: 1 };

  // Cached, synchronous texture fetch
  const tex = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.generateMipmaps = true;
  tex.anisotropy = 4;

  // Atlas region — atlas 0, source rect (0, 0, 512, 320)
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const img = tex.image;
  const atlasW = (img && img.width) ? img.width : rect.w;
  const atlasH = (img && img.height) ? img.height : rect.h;

  const uScale = rect.w / atlasW;
  const vScale = rect.h / atlasH;
  const uOffset = rect.x / atlasW;
  // Flip Y because Three's UV origin is bottom-left while atlas rect origin is top-left.
  const vOffset = 1.0 - (rect.y + rect.h) / atlasH;

  // Plane proportions honor the source rect aspect (512:320 -> 1.6:1)
  const aspect = rect.w / rect.h;
  const geometry = new THREE.PlaneGeometry(1, 1 / aspect, 1, 1);

  // TSL UV remap into the atlas sub-rect
  const sampleUv = vec2(
    uv().x.mul(uScale).add(uOffset),
    uv().y.mul(vScale).add(vOffset)
  );

  // Static composition — no lighting required, MeshBasicNodeMaterial
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(tex, sampleUv);
  material.transparent = true;
  material.depthWrite = true;
  material.side = THREE.DoubleSide;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scl.x, scl.y, scl.z);
  mesh.renderOrder = 0;

  // No cinematic primitives applied — node ships without primitive.
  // No interactions, no text content, no data bindings.
  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
